import os, pathlib, subprocess
ref=pathlib.Path('REFERENCE_BINARY.txt').read_text().strip(); port=['python','xsv_port.py']
cases=[]
def add(args,data=b'',env=None): cases.append((args,data,env))
base=b'h1,h2,h3,h1\na,b,c,d\ne,f,g,h\n'
for s in ['h1','h1[1]','1-3','3-1','-2','2-','!2','1,1','"h2"','']:
 add(['select','--',s],base)
for a in [[],['-n'],['-d',';']]: add(['count',*a],base.replace(b',',b';') if ';' in a else base)
for a in [[],['-s','0','-e','1'],['-s','1'],['-e','0'],['-i','2'],['-s','1','-l','0'],['-n','-s','1','-e','3']]: add(['slice',*a],base)
for a in [['foo'],['foo','-i'],['foo','-v'],['^a','-s','2'],['[a-z]','-n'],['(?i)A']]: add(['search',*a],base)
sortdata=b'h1,h2\n10,b\n-2,c\n2,a\n1.5,d\nno,e\n'
for a in [[],['-R'],['-N'],['-NR'],['-s','2'],['-n'],['-N','-s','1']]: add(['sort',*a],sortdata)
for a in [[],['-w','5'],['-p','0'],['-c','2']]: add(['table',*a],base)
add(['table'],b'h1,h2\n"a\tb",c\n'); add(['table'],'é,x\nabcdef,y\n'.encode())
fmtdata=b'h1,h2\n"a,b","a""b"\nline,"x\ny"\n'
for a in [[],['-t','h'],['--crlf'],['--ascii'],['--quote-always'],['--quote',"'"],['--escape','\\']]: add(['fmt',*a],fmtdata)
statsdata=b'i,f,s,n\n1,1.5,a,""\n2,2.5,b,""\n3,"",a,""\n'
for a in [[],['--everything'],['--mode'],['--median'],['--cardinality'],['--nulls'],['-s','2,1'],['-n'],['-j','1']]: add(['stats',*a],statsdata)
for vals in [[b'1e20',b'2e20'],[b'1e-20',b'2e-20'],[b'NaN',b'1'],[b'inf',b'1']]: add(['stats'],b'h\n'+b'\n'.join(vals)+b'\n')
freq=b'h1,h2\na,z\na,y\na,z\nb,z\nb,y\n'
for a in [[],['-l','1'],['-a','-l','1'],['-s','2']]: add(['frequency',*a],freq)
for c in ['headers','count','select','slice','search','sort','table','fmt','stats','frequency']: add([c,'--help'])
for a in [[],['--help'],['help'],['--list'],['--version'],['bogus'],['count','--bogus'],['select']]: add(a)
for data in [b'a,b\n1\n',b'a,b\r\n1\r\n',b'"a\nb",c\n1\n']: add(['count'],data)
failed=0
for args,data,extra_env in cases:
 env=os.environ.copy(); env.update(extra_env or {})
 a=subprocess.run([ref,*args],input=data,stdout=subprocess.PIPE,stderr=subprocess.PIPE,env=env)
 b=subprocess.run([*port,*args],input=data,stdout=subprocess.PIPE,stderr=subprocess.PIPE,env=env)
 if (a.returncode,a.stdout,a.stderr)!=(b.returncode,b.stdout,b.stderr):
  failed+=1; print('FAIL',args); print('R',a.returncode,repr(a.stdout),repr(a.stderr));print('P',b.returncode,repr(b.stdout),repr(b.stderr))
print('CASES',len(cases),'FAILED',failed)
raise SystemExit(bool(failed))
'@ | python -; cmd /c executable.cmd --version; git diff --check; git status --short","workdir":".","timeout_ms":60000});text(r)

